<?php use VazinCMS\Security; ?><article class="travel-card"><?php if($item['featured_image']):?><img src="<?=Security::e($item['featured_image'])?>" alt="" loading="lazy"><?php else:?><div class="card-placeholder">V</div><?php endif;?><div class="card-body"><h3><a href="/<?=$locale?>/<?=$type?>/<?=rawurlencode($item['slug'])?>"><?=Security::e($item['title'])?></a></h3><p><?=Security::e($item['excerpt']?:mb_substr(strip_tags($item['body']),0,150))?></p><a class="read-more" href="/<?=$locale?>/<?=$type?>/<?=rawurlencode($item['slug'])?>">ادامه مطلب</a></div></article>
